const units=[['Vapor',18,'Conceptos básicos de termodinámica y comportamiento del vapor.'],['Clasificación de calderas',22,'Generadores de vapor según su método de trabajo y aplicación.'],['Accesorios de calderas',22,'Componentes internos y externos, su función e importancia.'],['Sistemas de combustión',10,'Fuentes de calor, combustión y transferencia térmica.'],['Sistemas de alimentación',10,'Componentes y funcionamiento de la alimentación de agua.'],['Operación de calderas',22,'Operación segura, sistemas asociados y mantenimiento.'],['Turbinas de vapor',18,'Principios de funcionamiento y componentes.'],['Auxiliares de turbinas',14,'Sistemas que hacen posible el funcionamiento de la turbina.'],['Operación de turbinas',9,'Conducción de la planta y control de funcionamiento seguro.'],['Fluido térmico',8,'Descripción, operación, mantenimiento y aplicaciones navales.']];
