const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={done:[],notes:{},answers:{}};try{saved={...saved,...JSON.parse(localStorage.getItem('naval-study-v1')||'{}')}}catch{}let storageOK=true;function persist(){try{localStorage.setItem(window.localStudyKey||'naval-study-v1',JSON.stringify(saved));storageOK=true}catch{storageOK=false}return storageOK}
let topic=1,model='simple',mode='explore',selected='upper',placed=new Set(),explode=0,flow=true;
const app=document.querySelector('#app');let timerInterval;let oralIndex=0;
const questions=[['¿Qué es una caldera y cómo se produce el vapor?',0,'Explicá la transferencia de energía térmica al agua, el calentamiento y la vaporización. Distinguí el recipiente y las superficies donde se transfiere calor.'],['¿Qué diferencia a una caldera acuotubular de una humotubular?',1,'En la acuotubular el agua y la mezcla agua-vapor circulan dentro de los tubos; los gases calientes pasan por fuera. En la humotubular los gases circulan dentro de los tubos y el agua los rodea.'],['¿Para qué sirve el domo o colector superior?',2,'Recibe la mezcla agua-vapor, permite separar el vapor del agua y mantiene una reserva de agua. Relacionalo con los tubos hervidores y los descendentes.'],['¿Por qué circula el agua en una caldera de circulación natural?',4,'La diferencia de densidad entre el agua de los descendentes y la mezcla agua-vapor de los tubos calentados favorece la circulación. Señalá el recorrido en el modelo.'],['¿Dónde está la válvula de toma de vapor principal y qué hace?',2,'Comunica o aísla la caldera de la tubería principal. Bobbio la ubica a la salida del colector superior para vapor saturado o a la salida del sobrecalentador para vapor sobrecalentado. No confundas esta función con descargar sobrepresión.'],['¿Qué función cumple el sobrecalentador?',2,'Recibe vapor y le aporta calor adicional para elevar su temperatura por encima de la de saturación a la presión correspondiente. Relacionalo con el recorrido de gases.'],['¿Cómo transmite calor la combustión al agua?',3,'Explicá radiación desde la llama y los gases, convección del lado de los fluidos y conducción a través de la pared metálica.'],['¿Qué cambia entre la disposición A y la D?',1,'En el modelo A distinguí un colector superior y dos inferiores. La D tiene dos colectores, superior e inferior, y un horno lateral. Usá los dibujos de Bobbio para describir cada diseño.'],['¿Qué revisaría un maquinista durante la operación de una caldera?',5,'Organizá la respuesta en nivel de agua, presión, combustión, alimentación e indicaciones de seguridad. Las acciones concretas dependen del equipo y sus procedimientos.'],['¿Cómo transforma una turbina la energía del vapor en trabajo?',6,'Relacioná expansión, toberas o álabes fijos, álabes móviles, rotor y eje. Explicá la diferencia entre acción y reacción.'],['¿Para qué sirven los sistemas auxiliares de una turbina?',7,'Relacioná lubricación con cojinetes, sellado con fugas y, en plantas de condensación, condensador y extracción de aire con la presión de escape.'],['¿Qué controlarías al operar una turbina?',8,'Velocidad, presión y temperatura del vapor, lubricación, temperatura de cojinetes, vibraciones y protecciones. Evitá inventar valores de ajuste.'],['¿Qué caracteriza a un sistema de calentamiento por fluido térmico?',9,'Un fluido transporta calor desde el calentador a los consumidores y retorna al circuito. El funcionamiento y los límites deben estudiarse con el manual específico.']];
const types={simple:{name:'Acuotubular simple',desc:'Dos colectores y un circuito visible: una base conceptual para entender dónde va cada pieza.',source:'Modelo didáctico general; no corresponde a un fabricante.'},D:{name:'Tipo D',desc:'Dos colectores y horno lateral. Compará su disposición con la caldera básica.',source:'Bobbio · capítulo 5 · desde página impresa 29.'},A:{name:'Tipo A',desc:'Un colector superior y dos inferiores. Vista conceptual de los haces que los vinculan.',source:'Bobbio · capítulo 4 · desde página impresa 21. Se omiten los detalles del horno dividido.'},M:{name:'Tipo M',desc:'Horno doble, colectores y pared lateral con techo tubular. La geometría muestra relaciones generales.',source:'Bobbio · apartados 4.6–4.7 · páginas impresas 25–26. Se simplifican pantallas y sobrecalentador.'},catalog:{name:'Más tipos del libro',desc:'Catálogo para continuar ampliando el taller con referencias verificadas.',source:'Bobbio · índice general y capítulos 6–7.'}};
function renderTopics(){if(window.currentSubject&&window.currentSubject!=='termicas'){window.renderSubjectTopics?.();return}document.querySelector('#topics').innerHTML=units.map((u,i)=>`<button class="${topic===i?'active':''}" data-topic="${i}"><small>${String(i+1).padStart(2,'0')}</small> ${esc(u[0])}</button>`).join('');document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{topic=+b.dataset.topic;if(location.hash==='#oral'&&window.renderGuidedReview){renderGuidedReview(topic);return}if(topic===1||topic===2||topic===4){location.hash='taller';render()}else{showUnit(topic);renderTopics()}})}
function head(k,title,desc){return `<div class="page-top"><div class="eyebrow">${k}</div><h1>${title}</h1><p class="lead">${desc}</p></div>`}
function render(){window.cleanupGuided?.();window.configurePracticeSubject?.();window.cleanupExam?.();clearInterval(timerInterval);window.stopModel?.();renderTopics();let route=location.hash.slice(1)||'taller';window.syncStudyLayout?.(route);window.syncSubjectChrome?.();if(route==='oral'&&window.renderGuidedReview){renderGuidedReview();return}if(window.currentSubject&&window.currentSubject!=='termicas'&&!['cuenta','usuarios'].includes(route)){renderSubject(route);return}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));if(route==='cuenta'){renderAccount();return}if(route==='usuarios'){renderUsers();return}if(route==='progreso'){renderProgressPage();return}if(route==='profesor'){renderProfessor();return}if(route==='taller'){renderWorkshop();return}if(route==='programa'){app.innerHTML=head('EL MAPA DE LA MATERIA','Diez unidades. Un sistema.','Elegí una unidad para ver su alcance y marcar tu progreso.')+`<div class="stats"><div class="stat"><strong>10</strong><span>unidades temáticas</span></div><div class="stat"><strong>153</strong><span>horas cátedra · 102 h reloj</span></div><div class="stat"><strong>${saved.done.length}/10</strong><span>unidades repasadas</span></div></div><input class="search" aria-label="Buscar unidades" placeholder="Buscar un tema del programa…"><div class="unit-list"></div><div class="section-head"><h2>Temas de clase · Modo Completo</h2></div><div class="grid">${["Propiedades del combustible","Circuito de combustible","Alimentación de calderas · circuito completo","Mantenimiento y posibles fallas"].map((title,i)=>`<article class="card"><span class="tag">CLASE · COMPLETO</span><h3>${title}</h3><p>Propiedades, componentes, conexiones, funcionamiento, mantenimiento y diagnóstico según corresponda.</p><a class="button secondary" href="#profesor" onclick="exam.unit=${i+10};exam.scope='completo'">Practicar con el profesor →</a></article>`).join('')}</div><p class="source">Fuente: <a target="_blank" rel="noopener" href="${sources.program}">Programa analítico · Escuela Nacional Fluvial ↗</a></p>`;function list(q=''){document.querySelector('.unit-list').innerHTML=units.map((u,i)=>({u,i})).filter(({u})=>u.join(' ').toLowerCase().includes(q.toLowerCase())).map(({u,i})=>`<div class="unit-row"><span class="number">${i+1}</span><div><h3>${u[0]}</h3><p>${u[2]} · ${u[1]} h cátedra</p></div><label><input type="checkbox" data-done="${i}" ${saved.done.includes(i)?'checked':''}> Repasada</label><button data-unit="${i}">Ver unidad</button></div>`).join('')||'<div class="empty">No hay coincidencias.</div>';document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>showUnit(+b.dataset.unit));document.querySelectorAll('[data-done]').forEach(b=>b.onchange=()=>{const i=+b.dataset.done;saved.done=saved.done.filter(x=>x!==i);if(b.checked)saved.done.push(i);persist();const q=document.querySelector('.search').value;render();document.querySelector('.search').value=q;list(q)})}list();document.querySelector('.search').oninput=e=>list(e.target.value)}else if(route==='esquemas'){app.innerHTML=head('MIRAR PARA ENTENDER','Esquemas y válvulas','Referencias visuales verificadas dentro de los materiales compartidos.')+`<div class="note"><strong>Válvula de cuello: identificación pendiente.</strong> No encontramos ese nombre exacto en los textos revisados. Las figuras de abajo corresponden a la toma de vapor principal de caldera. Hay que confirmar qué uso le da el profesor antes de equipararlas.</div><div class="two-col"><div><h2>Toma de vapor principal</h2><p>Comunica o aísla la caldera de la tubería principal. Puede estar a la salida del colector superior o del sobrecalentador, según la instalación.</p><p class="source"><a href="${sources.book}" target="_blank" rel="noopener">Bobbio · apartado 9.2 · pp. impresas 91–93 ↗</a><br><a href="${sources.atlas}" target="_blank" rel="noopener">Atlas · figuras 97–98 · p. impresa 61 / PDF 62 ↗</a></p><a class="button secondary" href="assets/valvulas.png" target="_blank" rel="noopener">Abrir imagen completa ↗</a></div><div class="diagram"><img src="assets/valvulas.png" alt="Atlas: figuras 97 y 98, cortes de válvulas de toma principal de vapor con leyenda de componentes"></div></div>`}else if(route==='oral'){renderOral()}else if(route==='biblioteca'){app.innerHTML=head('MATERIAL DE CONSULTA','Tu biblioteca de a bordo.','Los enlaces abren los originales de Drive; pueden requerir tu cuenta de Google.')+[[sources.program,'Programa analítico','Diez unidades, objetivos y carga horaria.'],[sources.book,'Calderas Marinas I · Enrique Bobbio','Clasificación, tipos de calderas, accesorios internos y externos.'],[drive('1eK0ar8DqgNc-jdxkMpxSqck99HfkB_DU'),'Calderas Marinas II · Enrique Bobbio','Combustión, combustible, alimentación, operación, mantenimiento y fallas.'],[sources.atlas,'Atlas de Calderas Marinas','Dibujos de equipos y cortes de componentes.'],[sources.class,'Transcripción de clase · Daldin','Explicaciones y recomendaciones para el examen oral.'],[drive('16XsJDz4UTOTcHuyWOAiXM7pieSsKaFJK'),'Cuestionario de Máquinas Térmicas · Parte I 2026','Preguntas de los materiales compartidos.'],['https://drive.google.com/drive/folders/1DGk0yiXiW0m7mtrI37Q1jAU9Z3QLruc0','Carpeta completa de la materia','Acceso al resto de apuntes, guías y libros.']].map(([url,title,desc])=>`<a class="library-link" href="${url}" target="_blank" rel="noopener"><strong>${title} ↗</strong><span>${desc}</span></a>`).join('')}else if(route==='notas'){app.innerHTML=head('ORDENAR LO APRENDIDO','Un lugar para tus notas.','Anotá lo que entendiste, las dudas y las preguntas que aparecen en clase.')+`<label for="note-topic">Unidad</label> <select id="note-topic">${units.map((u,i)=>`<option value="${i}">${i+1}. ${u[0]}</option>`).join('')}</select><p></p><textarea id="note-text" aria-label="Notas de la unidad" placeholder="¿Qué aprendí? ¿Qué necesito revisar? ¿Qué quiero preguntarle al profesor?"></textarea><p class="save-status" role="status"></p><button id="export-notes" class="secondary">Descargar notas y progreso</button><p class="source">Guardado local en este dispositivo y navegador. Descargá una copia para conservar tus notas.</p>`;const s=document.querySelector('#note-topic'),t=document.querySelector('#note-text');s.value=topic;function fill(){t.value=saved.notes[s.value]||''}fill();s.onchange=fill;t.oninput=()=>{saved.notes[s.value]=t.value;document.querySelector('.save-status').textContent=persist()?'Notas guardadas.':'No se pudo guardar. Descargá una copia.'};document.querySelector('#export-notes').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}));a.download='cuaderno-naval.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}else{location.hash='taller'}}
function showUnit(i){topic=i;document.querySelector('#unit-content').innerHTML=`<div class="eyebrow">UNIDAD ${i+1} · ${units[i][1]} H CÁTEDRA</div><h2>${units[i][0]}</h2><p>${units[i][2]}</p><p>Prepará una explicación que conecte definición, ubicación, función, funcionamiento y consecuencias de una falla.</p><div class="actions"><a class="button" href="#oral" onclick="document.querySelector('dialog').close()">Practicar oral</a><a class="button secondary" href="#notas" onclick="document.querySelector('dialog').close()">Tomar notas</a></div><p class="source"><a href="${sources.program}" target="_blank" rel="noopener">Consultar programa original ↗</a></p>`;document.querySelector('dialog').showModal()}
document.querySelector('.close').onclick=()=>document.querySelector('dialog').close();
function renderOral(filter='all'){const qs=questions.map((q,i)=>({q,i})).filter(({q})=>filter==='all'||q[1]===+filter);if(!qs.some(x=>x.i===oralIndex))oralIndex=qs[0]?.i??0;const q=questions[oralIndex];app.innerHTML=head('ENSAYO DE EXAMEN','Explicalo con tus palabras.','Leé la pregunta, prepará un dibujo y ensayá una respuesta de dos minutos. Después compará los puntos clave.')+`<div class="oral-card"><div class="card-top"><select id="oral-filter" aria-label="Filtrar preguntas"><option value="all">Todas las unidades</option>${units.map((u,i)=>`<option value="${i}">${i+1}. ${u[0]}</option>`).join('')}</select><span class="timer" id="timer">02:00</span></div><p class="eyebrow">UNIDAD ${q[1]+1} · ${units[q[1]][0]}</p><h2>${q[0]}</h2><textarea id="oral-response" placeholder="Escribí palabras clave para ordenar tu respuesta…" aria-label="Tu respuesta">${esc(saved.answers[oralIndex]||'')}</textarea><div class="actions"><button id="start-timer">Iniciar 2 minutos</button><button id="reveal" class="secondary">Ver puntos clave</button><button id="next-question" class="secondary">Otra pregunta →</button></div><div id="answer" hidden class="answer"></div><p class="source">Guía de repaso orientativa; no es una corrección automática ni una predicción del examen.</p></div>`;document.querySelector('#oral-filter').value=filter;document.querySelector('#oral-filter').onchange=e=>renderOral(e.target.value);document.querySelector('#oral-response').oninput=e=>{saved.answers[oralIndex]=e.target.value;persist()};document.querySelector('#reveal').onclick=()=>{const a=document.querySelector('#answer');a.hidden=!a.hidden;a.textContent=q[2]};document.querySelector('#next-question').onclick=()=>{clearInterval(timerInterval);const n=qs.findIndex(x=>x.i===oralIndex);oralIndex=qs[(n+1)%qs.length].i;renderOral(filter)};document.querySelector('#start-timer').onclick=()=>{clearInterval(timerInterval);let n=120;document.querySelector('#timer').textContent='02:00';timerInterval=setInterval(()=>{n--;document.querySelector('#timer').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(n<=0){clearInterval(timerInterval);document.querySelector('#timer').textContent='Tiempo cumplido'}},1000)}}
